// Generated by `cargo xtask add-card`.
// Round-trip regression test for the generated test suite.
//
// Card           : Pirate Ship
// Set            : lea
// Collector #    : 70

#[test]
fn round_trip() {
    let text = "This creature can't attack unless defending player controls an Island.\n{T}: This creature deals 1 damage to any target.\nWhen you control no Islands, sacrifice this creature.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    assert_eq!(
        reprinted, text,
        "unparse must preserve the normalized oracle text"
    );
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
